import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import {
  mcpAdfToText,
  mcpCustomField,
  mcpDescription,
  processCustomFieldValue,
  simplifyLinks,
} from "../dist/preflights/fabric-project-state/mcp.js";
import { planDigest, planSnapshot } from "../dist/preflights/fabric-project-state/plan.js";

// Goldens generated by test/fixtures/project-state-parity/generate.py: every
// case's REST issues are run through the REAL mcp-atlassian 0.23.1 server
// models (the code deployed in devbot-proxy) and the REAL Fabric coordinator
// Python (project_coordinator.ticket_plan_snapshot/ticket_plan_digest from
// fabric-access-ai-dev, the functions actions.py uses for approval hashes).
// The TypeScript must reproduce the same MCP projection, snapshot, and digest
// from the raw REST issues, proving REST reads and MCP reads digest
// identically without any live Jira call.
const golden = JSON.parse(
  readFileSync(
    new URL("./fixtures/project-state-parity/parity-goldens.json", import.meta.url),
    "utf8",
  ),
);

test("goldens were generated by the deployed mcp-atlassian version", () => {
  assert.equal(golden.generator.mcp_atlassian, "0.23.1");
  assert.ok(golden.cases.length >= 15);
});

for (const entry of golden.cases) {
  test(`parity: ${entry.name}`, () => {
    const { team_field_id: teamFieldId, implementation_label: implementationLabel } = entry;
    const snapshot = planSnapshot(entry.rest, teamFieldId, implementationLabel);
    assert.deepEqual(snapshot, entry.snapshot);
    assert.equal(planDigest(snapshot), entry.digest);

    // The per-issue MCP projection pins the ported transformations exactly:
    // the flattened description, the wrapped custom team field, and the
    // simplified snake_case links the server returns.
    assert.equal(entry.rest.length, entry.mcp.length);
    entry.rest.forEach((issue, index) => {
      const projected = entry.mcp[index];
      const fields = issue.fields;
      const emulated = { key: projected.key };
      const description = mcpDescription(fields.description);
      if (description !== undefined) emulated.description = description;
      if (Object.hasOwn(fields, teamFieldId))
        emulated[teamFieldId] = mcpCustomField(fields[teamFieldId]);
      const links = simplifyLinks(fields.issuelinks);
      if (links.length) emulated.issuelinks = links;
      assert.deepEqual(emulated, projected);
    });
  });
}

test("links are invisible to the hash but blocks collapse to the same digest", () => {
  // The Python runner cannot observe any link through the mcp-atlassian
  // shape, so every link corpus case digests like a link-free ticket with
  // identical other fields.
  const digests = new Set(
    golden.cases
      .filter((entry) => entry.name.startsWith("links-") || entry.name === "description-null")
      .map((entry) => entry.digest),
  );
  assert.equal(digests.size, 1);
});

test("malformed ADF, custom field, and link values fail closed", () => {
  assert.throws(() => mcpAdfToText({ type: "mention", attrs: [] }), /Invalid ADF attrs/);
  assert.throws(
    () => mcpAdfToText({ type: "inlineCard", attrs: { data: [] } }),
    /Invalid ADF card data/,
  );
  assert.throws(
    () => mcpAdfToText({ type: "paragraph", content: [{ type: "text", text: 5 }] }),
    /Invalid ADF text/,
  );
  const deep = (depth) =>
    depth === 0 ? { type: "text", text: "bottom" } : { type: "x", content: [deep(depth - 1)] };
  assert.throws(() => mcpAdfToText(deep(250)), /ADF nesting too deep/);
  // Only list items recurse in _process_custom_field_value; the depth cap
  // fails closed where Python would keep recursing toward its own limit.
  const deepField = (depth) => (depth === 0 ? { id: "x" } : [deepField(depth - 1)]);
  assert.throws(() => processCustomFieldValue(deepField(250)), /Custom field nesting too deep/);
  assert.throws(() => simplifyLinks([{ id: null }]), /Invalid Jira link id/);
  assert.throws(
    () => simplifyLinks([{ type: { id: null, name: "Blocks" } }]),
    /Invalid Jira link type id/,
  );
  assert.throws(
    () => simplifyLinks([{ inwardIssue: { id: null, key: "X-1" } }]),
    /Invalid Jira linked issue id/,
  );
  // Non-array link collections are silently emptied by the server model
  // (models/jira/link.py guards with isinstance), not an error.
  assert.deepEqual(simplifyLinks("garbage"), []);
  assert.deepEqual(simplifyLinks(null), []);
});
